import { useTranslation } from 'react-i18next';
import { defaultLanguage } from './config';

/**
 * Prefixes an internal absolute path with the locale segment (e.g. `/ro`) for
 * every language but the default. Used everywhere an internal `href`/`Link to`
 * is built from a manifest path or a static route, so a Romanian page's links
 * stay on `/ro/...` instead of falling back to English.
 */
export function localizePath(path, lang) {
  if (!lang || lang === defaultLanguage) return path;
  if (path === '/') return `/${lang}`;
  return `/${lang}${path}`;
}

/** Returns a `localizePath` bound to the current i18n language. */
export function useLocalizedPath() {
  const { i18n } = useTranslation('edb');
  return (path) => localizePath(path, i18n.language);
}
